package matteroverdrive.blockentity;

import matteroverdrive.item.ContractItem;import matteroverdrive.menu.StarMapMenu;import matteroverdrive.registry.*;import matteroverdrive.starmap.*;import net.minecraft.ChatFormatting;import net.minecraft.core.BlockPos;import net.minecraft.nbt.CompoundTag;import net.minecraft.network.chat.Component;import net.minecraft.server.level.*;import net.minecraft.world.MenuProvider;import net.minecraft.world.entity.Mob;import net.minecraft.world.entity.item.ItemEntity;import net.minecraft.world.entity.player.*;import net.minecraft.world.inventory.*;import net.minecraft.world.item.ItemStack;import net.minecraft.world.level.Level;import net.minecraft.world.level.block.entity.BlockEntity;import net.minecraft.world.level.block.state.BlockState;import javax.annotation.Nullable;import java.util.UUID;
public class StarMapBlockEntity extends BlockEntity implements MenuProvider{
 public static final int ENCOUNTER_NONE=0,ENCOUNTER_ASTEROIDS=1,ENCOUNTER_SLINGSHOT=2,ENCOUNTER_ANDROID_INTERCEPT=3,ENCOUNTER_SIGNAL_ECHO=4,ENCOUNTER_HOSTILE_FLEET=5;
 public static final int ECON_NONE=0,ECON_SCOUT=1,ECON_COLONIZER=2,ECON_FACTORY=3,ECON_HANGAR=4,ECON_COLONIZE=5,ECON_EXTRACTOR=6,ECON_GENERATOR=7,ECON_RESIDENTIAL=8;
 private static final int SCOUT_BUILD_TICKS=3600,COLONIZER_BUILD_TICKS=5000,FACTORY_BUILD_TICKS=8000,HANGAR_BUILD_TICKS=4800,EXTRACTOR_BUILD_TICKS=14400,GENERATOR_BUILD_TICKS=14400,RESIDENTIAL_BUILD_TICKS=6000,FLEET_MAX_HULL=100,FLEET_MAX_SHIELD=60,FLEET_BASE_FIREPOWER=20,FLEET_ATTACK_COOLDOWN=20;
 private int currentQuadrant,currentStar,currentPlanet,destinationQuadrant,destinationStar,destinationPlanet;private boolean traveling;private long travelStartTime,travelEndTime;private int travelDuration,encounterCode,lastEncounterCode;private long encounterTriggerTime;private boolean encounterResolved=true;@Nullable private UUID fleetOwner;private int fleetHull=100,fleetShield=60,fleetFirepower=20,fleetVictories;private boolean fleetCombat;private int enemyHull,enemyMaxHull,enemyFirepower;private long fleetCombatStarted,lastFleetAttack;private int scoutShips,colonizerShips,buildAction;private long buildEndTime;private int buildQuadrant,buildStar,buildPlanet;
 public StarMapBlockEntity(BlockPos p,BlockState s){super(ModBlockEntities.STAR_MAP.get(),p,s);}public static void tick(Level l,BlockPos p,BlockState s,StarMapBlockEntity m){if(l.isClientSide)return;long t=l.getGameTime();m.finishBuildIfDue(t);m.resolveEncounterIfDue(l,t);m.finishTravelIfDue(t);}private StarMapGalaxyData.PlanetState currentState(){return level instanceof ServerLevel sl?StarMapGalaxyData.get(sl).planet(currentQuadrant,currentStar,currentPlanet):new StarMapGalaxyData.PlanetState();}
 public ContainerData dataFor(Player v){return new ContainerData(){public int get(int i){int a=0,d=0;for(var s:v.getInventory().items)if(s.getItem() instanceof ContractItem){a++;if(ContractItem.complete(s))d++;}var ps=currentState();return switch(i){case 0->a;case 1->d;case 2->currentQuadrant;case 3->currentStar;case 4->currentPlanet;case 5->destinationQuadrant;case 6->destinationStar;case 7->destinationPlanet;case 8->remainingTicks();case 9->travelDuration;case 10->traveling?1:0;case 11->encounterResolved?lastEncounterCode:encounterCode;case 12->encounterResolved?0:encounterRemainingTicks();case 13->encounterResolved?1:0;case 14->fleetHull;case 15->fleetShield;case 16->fleetFirepower;case 17->fleetCombat?1:0;case 18->enemyHull;case 19->enemyMaxHull;case 20->fleetVictories;case 21->fleetAttackCooldown();case 22->scoutShips;case 23->colonizerShips;case 24->buildAction;case 25->buildRemainingTicks();case 26->!ps.hasOwner()?0:ps.isOwner(v.getUUID())?1:2;case 27->ps.hasBase()?1:0;case 28->ps.hasShipFactory()?1:0;case 29->ps.hangars();case 30->ps.fleetCapacity();case 31->ps.matterExtractors();case 32->ps.powerGenerators();case 33->ps.residential();case 34->ps.energyProduction();case 35->ps.matterProduction();case 36->ps.population();case 37->ps.happinessHundredths();case 38->ps.buildingCapacity();case 39->ps.buildingCount();default->0;};}public void set(int i,int v){}public int getCount(){return 40;}};}
 private boolean bind(ServerPlayer p){if(!(level instanceof ServerLevel sl)||fleetOwner!=null&&!fleetOwner.equals(p.getUUID()))return false;if(fleetOwner==null){fleetOwner=p.getUUID();StarMapGalaxyData.get(sl).ensureHomeworld(currentQuadrant,currentStar,currentPlanet,fleetOwner);setChanged();}return true;}
 public boolean requestTravel(ServerPlayer p,int q,int s,int pl){if(level==null||level.isClientSide||!StarMapCatalog.validPosition(q,s,pl))return false;finishTravelIfDue(level.getGameTime());if(!bind(p)){msg(p,"Star Map fleet is bound to another commander.",ChatFormatting.RED);return false;}if(buildAction!=0){msg(p,"Star Map: colony construction must finish before departure.",ChatFormatting.YELLOW);return false;}if(fleetCombat||traveling)return false;if(q==currentQuadrant&&s==currentStar&&pl==currentPlanet)return false;int dur=StarMapCatalog.travelTicks(currentQuadrant,currentStar,currentPlanet,q,s,pl);if(dur<=0)return false;destinationQuadrant=q;destinationStar=s;destinationPlanet=pl;traveling=true;travelDuration=dur;travelStartTime=level.getGameTime();travelEndTime=travelStartTime+dur;fleetShield=60;scheduleEncounter(dur);setChanged();msg(p,"Star Map journey started: "+StarMapCatalog.planet(q,s,pl).name()+" ("+Math.max(1,dur/20)+"s)",ChatFormatting.AQUA);return true;}
 public boolean requestEconomyAction(ServerPlayer p,int action){if(!(level instanceof ServerLevel sl)||action<1||action>8)return false;if(!bind(p)){msg(p,"Star Map economy is bound to another commander.",ChatFormatting.RED);return false;}if(traveling||fleetCombat)return false;StarMapGalaxyData data=StarMapGalaxyData.get(sl);var ps=data.planet(currentQuadrant,currentStar,currentPlanet);if(action==ECON_COLONIZE){if(ps.hasOwner()||colonizerShips<=0)return false;if(!data.colonize(currentQuadrant,currentStar,currentPlanet,p.getUUID()))return false;colonizerShips--;consumePhysicalShip(p,"colonizer_ship");setChanged();msg(p,"Colonizer deployed: Base established and planet ownership secured.",ChatFormatting.GREEN);return true;}if(!ps.isOwner(p.getUUID())||!ps.hasBase()||buildAction!=0)return false;int dur;switch(action){case ECON_SCOUT->{if(!ps.hasShipFactory()||scoutShips+colonizerShips>=ps.fleetCapacity())return false;dur=SCOUT_BUILD_TICKS;}case ECON_COLONIZER->{if(!ps.hasShipFactory()||scoutShips+colonizerShips>=ps.fleetCapacity())return false;dur=COLONIZER_BUILD_TICKS;}case ECON_FACTORY->{if(ps.hasShipFactory())return false;dur=FACTORY_BUILD_TICKS;}case ECON_HANGAR->{if(ps.hangars()>=8)return false;dur=HANGAR_BUILD_TICKS;}case ECON_EXTRACTOR->{if(ps.matterExtractors()>=16)return false;dur=EXTRACTOR_BUILD_TICKS;}case ECON_GENERATOR->{if(ps.powerGenerators()>=16)return false;dur=GENERATOR_BUILD_TICKS;}case ECON_RESIDENTIAL->{if(ps.residential()>=16)return false;dur=RESIDENTIAL_BUILD_TICKS;}default->{return false;}}buildAction=action;buildQuadrant=currentQuadrant;buildStar=currentStar;buildPlanet=currentPlanet;buildEndTime=level.getGameTime()+dur;setChanged();msg(p,"Star Map construction started: "+economyName(action)+" ("+Math.max(1,dur/20)+"s)",ChatFormatting.AQUA);return true;}
 private void finishBuildIfDue(long now){if(buildAction==0||level==null||now<buildEndTime||!(level instanceof ServerLevel sl))return;int a=buildAction;buildAction=0;buildEndTime=0;StarMapGalaxyData d=StarMapGalaxyData.get(sl);boolean ok=fleetOwner!=null&&d.planet(buildQuadrant,buildStar,buildPlanet).isOwner(fleetOwner);if(ok)switch(a){case ECON_SCOUT->{scoutShips++;spawnShipItem(sl,"scout_ship");}case ECON_COLONIZER->{colonizerShips++;spawnShipItem(sl,"colonizer_ship");}case ECON_FACTORY->d.addShipFactory(buildQuadrant,buildStar,buildPlanet,fleetOwner);case ECON_HANGAR->d.addHangar(buildQuadrant,buildStar,buildPlanet,fleetOwner);case ECON_EXTRACTOR->d.addMatterExtractor(buildQuadrant,buildStar,buildPlanet,fleetOwner);case ECON_GENERATOR->d.addPowerGenerator(buildQuadrant,buildStar,buildPlanet,fleetOwner);case ECON_RESIDENTIAL->d.addResidential(buildQuadrant,buildStar,buildPlanet,fleetOwner);}setChanged();if(ok)announce(level,"Star Map construction complete: "+economyName(a)+".",ChatFormatting.GREEN);}
 private void spawnShipItem(ServerLevel sl,String id){ItemStack stack=new ItemStack(ModItems.get(id).get());CompoundTag t=stack.getOrCreateTag();t.putUUID("FleetConsole",worldPosition.asLong()==0&&fleetOwner!=null?fleetOwner:UUID.nameUUIDFromBytes((sl.dimension().location()+":"+worldPosition).getBytes()));t.putInt("Quadrant",buildQuadrant);t.putInt("Star",buildStar);t.putInt("Planet",buildPlanet);ItemEntity e=new ItemEntity(sl,worldPosition.getX()+.5,worldPosition.getY()+1.2,worldPosition.getZ()+.5,stack);e.setDefaultPickUpDelay();sl.addFreshEntity(e);}
 private void consumePhysicalShip(ServerPlayer p,String id){for(int i=0;i<p.getInventory().getContainerSize();i++){ItemStack s=p.getInventory().getItem(i);if(s.is(ModItems.get(id).get())){s.shrink(1);return;}}}
 private static String economyName(int a){return switch(a){case 1->"Scout Ship";case 2->"Colonizer Ship";case 3->"Ship Factory";case 4->"Ship Hangar";case 5->"Colonize";case 6->"Matter Extractor";case 7->"Power Generator";case 8->"Residential";default->"Idle";};}
 public boolean requestFleetAttack(ServerPlayer p){if(level==null||!fleetCombat||!traveling||fleetOwner==null||!fleetOwner.equals(p.getUUID()))return false;long n=level.getGameTime();if(n-lastFleetAttack<20)return false;lastFleetAttack=n;enemyHull=Math.max(0,enemyHull-fleetFirepower);if(enemyHull<=0){fleetVictories++;fleetCombat=false;travelEndTime+=Math.max(0,n-fleetCombatStarted);fleetCombatStarted=0;setChanged();return true;}int dmg=enemyFirepower,sh=Math.min(fleetShield,dmg);fleetShield-=sh;dmg-=sh;if(dmg>0)fleetHull=Math.max(0,fleetHull-dmg);if(fleetHull<=0){fleetCombat=false;traveling=false;destinationQuadrant=currentQuadrant;destinationStar=currentStar;destinationPlanet=currentPlanet;fleetHull=35;fleetShield=0;}setChanged();return true;}
 private void scheduleEncounter(int d){encounterCode=0;encounterResolved=true;lastEncounterCode=0;if(d<80)return;encounterCode=Math.floorMod(currentQuadrant*97+currentStar*53+currentPlanet*31+destinationQuadrant*211+destinationStar*127+destinationPlanet*71+d,5)+1;encounterTriggerTime=travelStartTime+Math.max(30,d/2L);encounterResolved=false;}
 private void resolveEncounterIfDue(Level l,long t){if(!traveling||encounterResolved||encounterCode==0||t<encounterTriggerTime)return;switch(encounterCode){case 1->travelEndTime+=100;case 2->travelEndTime=Math.max(t+20,travelEndTime-Math.min(80,Math.max(20,travelDuration/6L)));case 3->{travelEndTime+=120;spawnBoardingParty(l);}case 4->travelEndTime+=40;case 5->beginFleetCombat(l,t);}lastEncounterCode=encounterCode;encounterResolved=true;encounterTriggerTime=0;travelDuration=(int)Math.max(1,travelEndTime-travelStartTime);setChanged();}
 private void beginFleetCombat(Level l,long t){int th=Math.floorMod(destinationQuadrant*7+destinationStar*11+destinationPlanet*13,4);enemyMaxHull=60+th*20;enemyHull=enemyMaxHull;enemyFirepower=8+th*3;fleetCombat=true;fleetCombatStarted=t;lastFleetAttack=t-20;announce(l,"Star Map encounter: hostile fleet contact.",ChatFormatting.RED);}private void spawnBoardingParty(Level l){if(!(l instanceof ServerLevel sl))return;for(int i=0;i<3;i++){Mob a=(i==2?ModEntities.RANGED_ROGUE_ANDROID.get():ModEntities.ROGUE_ANDROID.get()).create(sl);if(a!=null){a.moveTo(worldPosition.getX()+.5+(i-1)*2,worldPosition.getY()+1,worldPosition.getZ()+2.5,0,0);sl.addFreshEntity(a);}}}
 private void announce(Level l,String s,ChatFormatting c){if(l instanceof ServerLevel sl)for(ServerPlayer p:sl.players())if(p.distanceToSqr(worldPosition.getCenter())<=1024)p.displayClientMessage(Component.literal(s).withStyle(c),false);}private static void msg(ServerPlayer p,String s,ChatFormatting c){p.displayClientMessage(Component.literal(s).withStyle(c),true);}private int remainingTicks(){return !traveling||level==null?0:(int)Math.max(0,travelEndTime-level.getGameTime());}private int encounterRemainingTicks(){return encounterResolved||level==null?0:(int)Math.max(0,encounterTriggerTime-level.getGameTime());}private int fleetAttackCooldown(){return !fleetCombat||level==null?0:(int)Math.max(0,20-(level.getGameTime()-lastFleetAttack));}private int buildRemainingTicks(){return buildAction==0||level==null?0:(int)Math.max(0,buildEndTime-level.getGameTime());}private void finishTravelIfDue(long t){if(!traveling||fleetCombat||t<travelEndTime)return;currentQuadrant=destinationQuadrant;currentStar=destinationStar;currentPlanet=destinationPlanet;traveling=false;fleetHull=Math.min(100,fleetHull+10);fleetShield=60;setChanged();}
 @Override protected void saveAdditional(CompoundTag t){super.saveAdditional(t);t.putInt("CurrentQuadrant",currentQuadrant);t.putInt("CurrentStar",currentStar);t.putInt("CurrentPlanet",currentPlanet);t.putInt("DestinationQuadrant",destinationQuadrant);t.putInt("DestinationStar",destinationStar);t.putInt("DestinationPlanet",destinationPlanet);t.putBoolean("Traveling",traveling);t.putLong("TravelStart",travelStartTime);t.putLong("TravelEnd",travelEndTime);t.putInt("TravelDuration",travelDuration);t.putInt("EncounterCode",encounterCode);t.putInt("LastEncounterCode",lastEncounterCode);t.putLong("EncounterTrigger",encounterTriggerTime);t.putBoolean("EncounterResolved",encounterResolved);if(fleetOwner!=null)t.putUUID("FleetOwner",fleetOwner);t.putInt("FleetHull",fleetHull);t.putInt("FleetShield",fleetShield);t.putInt("FleetFirepower",fleetFirepower);t.putInt("FleetVictories",fleetVictories);t.putBoolean("FleetCombat",fleetCombat);t.putInt("EnemyHull",enemyHull);t.putInt("EnemyMaxHull",enemyMaxHull);t.putInt("EnemyFirepower",enemyFirepower);t.putLong("FleetCombatStarted",fleetCombatStarted);t.putLong("LastFleetAttack",lastFleetAttack);t.putInt("ScoutShips",scoutShips);t.putInt("ColonizerShips",colonizerShips);t.putInt("BuildAction",buildAction);t.putLong("BuildEnd",buildEndTime);t.putInt("BuildQuadrant",buildQuadrant);t.putInt("BuildStar",buildStar);t.putInt("BuildPlanet",buildPlanet);}
 @Override public void load(CompoundTag t){super.load(t);currentQuadrant=t.getInt("CurrentQuadrant");currentStar=t.getInt("CurrentStar");currentPlanet=t.getInt("CurrentPlanet");destinationQuadrant=t.getInt("DestinationQuadrant");destinationStar=t.getInt("DestinationStar");destinationPlanet=t.getInt("DestinationPlanet");traveling=t.getBoolean("Traveling");travelStartTime=t.getLong("TravelStart");travelEndTime=t.getLong("TravelEnd");travelDuration=t.getInt("TravelDuration");encounterCode=t.getInt("EncounterCode");lastEncounterCode=t.getInt("LastEncounterCode");encounterTriggerTime=t.getLong("EncounterTrigger");encounterResolved=!t.contains("EncounterResolved")||t.getBoolean("EncounterResolved");fleetOwner=t.hasUUID("FleetOwner")?t.getUUID("FleetOwner"):null;fleetHull=t.contains("FleetHull")?t.getInt("FleetHull"):100;fleetShield=t.contains("FleetShield")?t.getInt("FleetShield"):60;fleetFirepower=t.contains("FleetFirepower")?t.getInt("FleetFirepower"):20;fleetVictories=t.getInt("FleetVictories");fleetCombat=t.getBoolean("FleetCombat");enemyHull=t.getInt("EnemyHull");enemyMaxHull=t.getInt("EnemyMaxHull");enemyFirepower=t.getInt("EnemyFirepower");fleetCombatStarted=t.getLong("FleetCombatStarted");lastFleetAttack=t.getLong("LastFleetAttack");scoutShips=Math.max(0,t.getInt("ScoutShips"));colonizerShips=Math.max(0,t.getInt("ColonizerShips"));buildAction=t.getInt("BuildAction");buildEndTime=t.getLong("BuildEnd");buildQuadrant=t.getInt("BuildQuadrant");buildStar=t.getInt("BuildStar");buildPlanet=t.getInt("BuildPlanet");if(buildAction<0||buildAction>8){buildAction=0;buildEndTime=0;}}
 @Override public Component getDisplayName(){return Component.translatable("block.matteroverdrive.star_map");}@Nullable @Override public AbstractContainerMenu createMenu(int id,Inventory i,Player p){return new StarMapMenu(id,i,this);}
}
